from copy import deepcopy


def migrate_configuration(configuration):
    """
    Migrate configuration to the new format.

    :param configuration: configuration to migrate

    :return: new configuration
    """
    new_configuration = deepcopy(configuration)
    executor = _get_executor(new_configuration)
    new_configuration['executor'] = _get_new_executor(new_configuration, executor)

    return new_configuration


def _get_executor(new_configuration):
    if 'executor' in new_configuration and 'type' in new_configuration['executor']:
        return new_configuration['executor']
    elif 'executor' in new_configuration:
        return {'type': 'ssh', 'ssh': new_configuration.pop('executor')}
    else:
        return {'type': 'local'}


def _get_new_executor(new_configuration, executor):
    new_executor = {}

    for key in ('sudo_password', 'namespace', 'pod', 'container'):
        if key in new_configuration:
            new_executor[key] = new_configuration.pop(key)
    _update_executor_type_and_value(new_executor, executor)

    return new_executor


def _update_executor_type_and_value(new_executor, executor):
    if 'sudo_password' in new_executor and any(
            key in new_executor for key in ('namespace', 'pod', 'container')):
        raise AssertionError('sudo_password is not allowed for k8s/lxc config in executor\'s old_configuration format.'
                             '\nPlease provide sudo_password with executor\'s new_configuration format.')
    if 'namespace' in new_executor:
        new_executor['type'] = 'k8s'
        new_executor['executor'] = executor
    elif 'container' in new_executor:
        new_executor['type'] = 'lxc'
        new_executor['executor'] = executor
    else:
        new_executor.update(executor)
